import fs from "fs";

// 添加自定义字段
export function utils() {
  const province = taiwan.province.map((item) => ({
    ...item,
    province: item.id.substring(0, 2),
  }));
  const city = taiwan.city.map((item) => ({
    ...item,
    province: item.id.substring(0, 2),
    city: item.id.substring(2, 4),
  }));
  const area = taiwan.area.map((item) => ({
    ...item,
    province: item.id.substring(0, 2),
    city: item.id.substring(2, 4),
    area: item.id.substring(4, 6),
  }));

  // 将结果写入一个新的json文件中
  fs.writeFileSync(
    "./taiwan.json",
    JSON.stringify({ province, city, area }, null, 2)
  );
  console.log("台湾省地址数据已更新");
}

